fn first_run(items: &[i32]) -> &[i32] {
    if items.is_empty() {
        return &items[..0];
    }
    let head = items[0];
    let mut end = 1;
    while end < items.len() && items[end] == head {
        end += 1;
    }
    &items[..end]
}

fn main() {
    let v = vec![5, 5, 5, 7, 5];
    println!("{:?}", first_run(&v));
    println!("{:?}", first_run(&[]));
    println!("{:?}", first_run(&[1, 2, 2, 2]));
}
